import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Diagnostics","description":"","frontmatter":{},"headers":[],"relativePath":"mlua/diagnostics.md","filePath":"mlua/diagnostics.md","lastUpdated":1789328014000}'),r={name:"mlua/diagnostics.md"};function s(n,e,i,c,l,h){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="diagnostics" tabindex="-1">Diagnostics <a class="header-anchor" href="#diagnostics" aria-label="Permalink to &quot;Diagnostics&quot;">​</a></h1><p>Every diagnostic carries a code, a source location, and a message. Codes are grouped by the compiler stage that produced them, so the prefix alone tells you roughly where in the pipeline the problem was caught.</p><h2 id="code-ranges" tabindex="-1">Code Ranges <a class="header-anchor" href="#code-ranges" aria-label="Permalink to &quot;Code Ranges&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Range</th><th>Stage</th><th>Meaning</th></tr></thead><tbody><tr><td><code>MLUA1xxx</code></td><td>Lexer</td><td>Malformed tokens: unterminated strings, bad numbers, invalid escapes</td></tr><tr><td><code>MLUA3xxx</code></td><td>Parser</td><td>Grammar errors: missing <code>end</code>, unexpected token, malformed declaration</td></tr><tr><td><code>MLUA42xx</code></td><td>Access</td><td>Visibility violations on <code>private</code> and <code>protected</code> members</td></tr><tr><td><code>MLUA43xx</code></td><td>Declarations</td><td>Bad <code>override</code>, <code>final</code>, <code>abstract</code>, or interface implementation</td></tr><tr><td><code>MLUA44xx</code></td><td>Types</td><td>Unknown members, wrong argument types, invalid assignments and operators</td></tr></tbody></table><p>Errors are always reported using the code from the <em>earliest</em> stage that fails. A chunk with a lexer error, for example, is never parsed or type-checked, since later stages depend on earlier ones succeeding.</p><h2 id="frequently-seen-codes" tabindex="-1">Frequently Seen Codes <a class="header-anchor" href="#frequently-seen-codes" aria-label="Permalink to &quot;Frequently Seen Codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Message</th><th>Typical cause</th></tr></thead><tbody><tr><td><code>MLUA3001</code></td><td>unexpected token after chunk body</td><td>An extra <code>end</code>, or a block closed twice</td></tr><tr><td><code>MLUA3013</code></td><td>unexpected token in type body</td><td>A plain statement placed inside a <code>class</code> or <code>interface</code> body</td></tr><tr><td><code>MLUA3017</code></td><td>expected an expression</td><td>A declaration keyword used where a value was expected</td></tr><tr><td><code>MLUA4206</code></td><td>member is private to a class</td><td>A <code>private</code> member read from outside its declaring class</td></tr><tr><td><code>MLUA4207</code></td><td>member is protected in a class</td><td>A <code>protected</code> member read from outside the class hierarchy</td></tr><tr><td><code>MLUA4403</code></td><td>operator applied to the wrong type</td><td>For example, <code>#</code> used on a value that has no length</td></tr><tr><td><code>MLUA4404</code></td><td>cannot assign one type to another</td><td>The annotation and the assigned value&#39;s type don&#39;t match</td></tr><tr><td><code>MLUA4410</code></td><td>type has no member named ...</td><td>A typo, the wrong type, or a member that was never declared</td></tr><tr><td><code>MLUA4411</code></td><td>argument expects one type but received another</td><td>A call argument doesn&#39;t satisfy the parameter&#39;s declared type</td></tr><tr><td><code>MLUA4412</code></td><td>enum member is read only</td><td>An assignment targets an enum member instead of a variable</td></tr></tbody></table><h2 id="reading-a-diagnostic" tabindex="-1">Reading a Diagnostic <a class="header-anchor" href="#reading-a-diagnostic" aria-label="Permalink to &quot;Reading a Diagnostic&quot;">​</a></h2><p>Diagnostics follow a fixed format:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=test:24:52 MLUA4206: secret is private to Base</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Part</th><th>Meaning</th></tr></thead><tbody><tr><td><code>=test</code></td><td>The chunk name - typically the file being compiled</td></tr><tr><td><code>24:52</code></td><td>Line and column where the offending token starts</td></tr><tr><td><code>MLUA4206</code></td><td>The diagnostic code</td></tr><tr><td><em>(remainder)</em></td><td>A human-readable explanation of what was rejected and why</td></tr></tbody></table><p>This format is stable and safe to parse with tooling - editors and build scripts can extract the chunk, position, and code with a simple pattern match.</p><h2 id="severity" tabindex="-1">Severity <a class="header-anchor" href="#severity" aria-label="Permalink to &quot;Severity&quot;">​</a></h2><p>There is only one severity level: <strong>error</strong>. A chunk with at least one diagnostic does not run - a mistyped member name, an illegal override, or a type mismatch is caught before the game ever executes that code, rather than surfacing as a runtime crash mid-session.</p><p>There are no warnings and no suppression directives (no <code>// eslint-disable</code>-style escape hatch). If you deliberately want a check relaxed for a specific value, annotate it as <code>any</code> or <code>object</code> instead - this makes the relaxation visible in the source rather than hidden in a comment.</p><h2 id="strict-analysis-versus-runtime-checked-execution" tabindex="-1">Strict analysis versus runtime-checked execution <a class="header-anchor" href="#strict-analysis-versus-runtime-checked-execution" aria-label="Permalink to &quot;Strict analysis versus runtime-checked execution&quot;">​</a></h2><p>The strict mode used by <code>AnalyzeSource</code> reports all type and access errors. The runtime-checked mode used during execution keeps syntax and type-mismatch errors but allows dynamic fields.</p>',17)])])}const u=t(r,[["render",s]]);export{p as __pageData,u as default};
